import {config} from './cloud.js';
let timer,currentEmployee,clockState,context,expanded=false,loading=false,generation=0,messageKey=null;
const time=v=>v?new Date(v).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit',timeZone:'America/New_York'}):'—';
async function request(path,body){const r=await fetch(config.url+'/rest/v1/'+path,{method:body?'POST':'GET',headers:{apikey:config.key,'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});const d=await r.json();if(!r.ok)throw Error(d.message||'Clock update failed');return d}
export async function mountClock(employee,jobs){context={employee,jobs};if(currentEmployee!==employee?.id){clearTimeout(timer);loading=false;currentEmployee=employee?.id;clockState=null;expanded=false;messageKey=null}let root=document.querySelector('#employee-clock');if(!employee){root?.remove();generation++;return}if(!root){root=document.createElement('section');root.id='employee-clock';root.setAttribute('aria-label','Shared employee time clock');document.body.append(root)}draw();const g=++generation;try{const rows=await request('employee_clock?employee_id=eq.'+encodeURIComponent(employee.id)+'&select=*');if(g!==generation)return;clockState=rows[0]||{clocked_in:false};draw()}catch(e){if(g===generation)draw(e.message)}}
function draw(error=''){const root=document.querySelector('#employee-clock');if(!root||!context.employee)return;root.innerHTML='<div class="clock-buttons"><button id="clock-toggle"><span></span><small></small></button></div><button id="clock-expand" class="clock-expand" aria-expanded="false">▾ Time clock</button><div id="clock-message" class="clock-message" role="status" hidden></div>';const button=root.querySelector('#clock-toggle'),inside=!!clockState?.clocked_in;button.querySelector('span').textContent=loading?'Saving…':!clockState?'Loading…':inside?'Clock Out':'Clock In';button.querySelector('small').textContent=inside?'In at '+time(clockState.last_in):clockState?.last_out?'Out at '+time(clockState.last_out):'Start your day';button.disabled=loading||!clockState;button.classList.toggle('clock-active',inside);button.onclick=()=>punch(!inside);root.querySelector('#clock-expand').onclick=()=>{expanded=!expanded;showMessage()};if(error){expanded=true;root.querySelector('#clock-message').textContent=error;root.querySelector('#clock-message').hidden=false}else showMessage()}
function showMessage(){const root=document.querySelector('#employee-clock');if(!root)return;const box=root.querySelector('#clock-message');root.querySelector('#clock-expand').setAttribute('aria-expanded',String(expanded));root.querySelector('#clock-expand').textContent=(expanded?'▴ ':'▾ ')+(clockState?.clocked_in?'Clocked in':'Clocked out');box.classList.remove('clock-fading');box.hidden=!expanded;if(!expanded)return;box.replaceChildren();const close=document.createElement('button');close.className='clock-close';close.textContent='×';close.setAttribute('aria-label','Close clock message');close.onclick=()=>{expanded=false;showMessage()};box.append(close);const add=(tag,text)=>{const e=document.createElement(tag);e.textContent=text;box.append(e)};if(!clockState?.clocked_in){add('h3','Thank you for all that you do!');if(clockState?.last_out)add('p','Clocked out at '+time(clockState.last_out));return}add('h3','Rise and Grind!');add('p','Today is '+new Date().toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric',year:'numeric',timeZone:'America/New_York'})+'.');const mine=context.jobs.filter(j=>j.employee===currentEmployee&&j.status!=='Complete'),high=context.jobs.filter(j=>j.area===context.employee.area&&j.priority==='High'&&j.status!=='Complete');add('h4','Your assigned work · '+mine.length+' jobs');if(!mine.length)add('p','No active assignments. Check open jobs in your shop or request work.');for(const j of mine)add('p','#'+j.id+' · '+j.title+' · '+j.customer+' · Qty '+j.qty+' parts · Rev '+j.revision+' · Due '+j.due+' · '+j.done+'/'+j.qty+' complete · '+j.status+(j.priority==='High'?' · 🔴 HIGH PRIORITY':''));add('h4','🔴 High priority in your shop · '+high.length);if(!high.length)add('p','No high-priority jobs in your shop area.');for(const j of high)add('p','#'+j.id+' · '+j.title+' · '+j.customer+' · Qty '+j.qty+' · Rev '+j.revision+' · Due '+j.due+' · '+j.status);add('strong','Please be sure to wear your Glasses and follow safety procedures.')}
async function punch(inside){if(loading||!clockState||clockState.clocked_in===inside)return;const id=currentEmployee;loading=true;draw();try{const result=await request('rpc/tps_clock',{employee_key:id,clock_in:inside});if(id!==currentEmployee)return;clockState=result;window.dispatchEvent(new CustomEvent('tps-clock-change',{detail:result}));expanded=true;messageKey=inside?'in':'out';clearTimeout(timer);timer=setTimeout(()=>{const box=document.querySelector('#clock-message');if(box)box.classList.add('clock-fading');timer=setTimeout(()=>{expanded=false;showMessage()},300)},14700);loading=false;draw()}catch(e){loading=false;if(id===currentEmployee)draw(e.message)}}
// Keep clock state current when the same badge is open on another station.
setInterval(()=>{if(currentEmployee&&!loading&&!document.hidden)mountClock(context.employee,context.jobs)},15000);
